// magpie / OpenCode provider plugin for Trae (ByteDance 的 AI IDE)。
//
// 两个 provider，各为一个站点：
//   - trae-cn      国区：授权页 www.trae.cn，换令牌 api.trae.com.cn，对话 api5-normal.mchost.guru
//   - trae-global  国际版：授权页 www.trae.ai，换令牌 api.trae.ai，对话 coresg-normal.trae.ai
//
// 站点由 provider id 决定，不由 base_url 或凭证 domain 猜测：猜错就是请求打到另一个
// 区域、上游回 401，错误来自上游几乎无法定位。
//
// 协议面（对话端点、SOLO 请求头、请求体 AES-256-GCM 加密、SSE 事件、模型表、
// 换令牌、签到、积分）整体对齐 llm-api 的 internal/relay/channel/trae —— 那是唯一
// 被生产跑过的一版实现，也是这个包的设计图纸。
//
// 这个文件只导出两个插件函数，别的什么都不导出：OpenCode 1.x 会拒绝一个导出里除了
// 插件还有别的东西的包。OpenCode 2.x 由 opencode2.mjs 适配。插件工厂在 lib/plugin.mjs。

import { SITES } from "./lib/sites.mjs"
import { makePlugin } from "./lib/plugin.mjs"

export const TraeCNPlugin = makePlugin(SITES["trae-cn"])
export const TraeGlobalPlugin = makePlugin(SITES["trae-global"])

// magpie / OpenCode provider 插件本体：一个站点一份。
//
// 对话链路与 llm-api 的 internal/relay/channel/trae 逐段对应：
//
//	客户端 OpenAI 请求 → prepareBody 归一化 → AES-256-GCM 加密 → base64 作 body
//	→ POST {api}/api/agent/v3/llm_utils_chat（SOLO 请求头 + x-request-pin）
//	→ SOLO SSE → OpenAI chunk / 聚合消息
//
// 两个容易踩的点：
//   - 上游恒回 SSE，`stream` 字段被忽略。客户端要非流式时得由这里聚合，
//     否则会把一堆 SSE 文本当成 JSON 交给客户端。
//   - 上游业务错误走 event:error，不是 HTTP 状态码。吞掉它就只剩一个空流，
//     客户端永远等不到内容也看不到原因。

import { createHash, randomUUID } from "node:crypto"

import { prepareBody } from "./payload.mjs"
import { encryptBody } from "./crypto.mjs"
import { PROFILE, soloHeaders } from "./headers.mjs"
import { EP, FUNCTIONS, SITES, WRONG_FUNCTION } from "./sites.mjs"
import { startIdeVersionRefresh } from "./version.mjs"
import { classify, classifyStreamError, errorOf } from "./errors.mjs"
import {
  SoloDecoder,
  Thoughts,
  aggregate,
  textCall,
  toolCallsOf,
  usageOf,
  chunkOf,
  completionOf,
} from "./sse.mjs"
import { TextTools } from "./tooltext.mjs"
import {
  startSignIn,
  exchangeToken,
  renewToken,
  fetchUserInfo,
  parseCredential,
  cleanToken,
  expiresOfJWT,
  newDeviceIDs,
} from "./oauth.mjs"
import { fetchModels, staticModels, modelsFrom } from "./models.mjs"
import { entUsage, checkinOf } from "./account.mjs"
import { enterpriseUsage, isEnterprise } from "./enterprise.mjs"

// EARLY_MS 是「请求前先刷新」的提前量：令牌剩余寿命不到这么多就先换掉。
const EARLY_MS = 60 * 1000
// LEAD_MS 是交给 magpie 的 auth.refreshLead：到期前这么久由 magpie 主动续期。
const LEAD_MS = 5 * 60 * 1000
// 模型清单缓存：上游模型表不常变，没必要每个请求都问一次。
const MODELS_TTL_MS = 5 * 60 * 1000

// 一次续期在各调用方之间共享：一个账号同时来多个请求，只花一次刷新令牌。
// 官方刷新会换发新的 refresh token，两个调用方同时花同一个就会有一个被拒。
const renewing = new Map()

const trimSlash = (s) => String(s ?? "").replace(/\/+$/, "")

// usable 判断一份存储的登录能不能用。
export function usable(auth) {
  if (!auth || auth.type !== "oauth") return false
  return !!(cleanToken(auth.access) || auth.refresh)
}

// expired 判断访问令牌是否临近到期。
export function expired(auth, now = Date.now()) {
  const exp = Number(auth?.expires)
  return Number.isFinite(exp) && exp > 0 && now >= exp - EARLY_MS
}

// account 把存储的登录归一化成请求要用的形态。
function account(auth) {
  return {
    access: cleanToken(auth.access),
    refresh: String(auth.refresh ?? ""),
    expires: Number(auth.expires) || 0,
    uid: String(auth.uid ?? ""),
    name: String(auth.accountId ?? ""),
    machineId: String(auth.machineId ?? auth.machine_id ?? ""),
    deviceId: String(auth.deviceId ?? auth.device_id ?? ""),
    devicePublicKey: String(auth.devicePublicKey ?? ""),
    devicePrivateKey: String(auth.devicePrivateKey ?? ""),
    domain: String(auth.domain ?? ""),
    // 登录时授权页回传的 host：它就是「是不是企业账号」的判据（见 enterprise.mjs）
    host: String(auth.host ?? ""),
    // console 拒过对话的席位：跟账号一起存下来，之后直接走消费网关
    consoleChat: auth.consoleChat,
  }
}

// modelHost 是这次请求要打哪个模型网关。
//
// 企业账号的对话走它自己租户的 console（计费计在席位池上）；被 console 拒过（4245）
// 的席位走消费网关——console 不是每个租户都接对话。两个都不是就看站点自己的。
function modelHost(site, a) {
  const consoleHost = site?.console?.host
  if (consoleHost && isEnterprise(a, site) && a.consoleChat !== false) return trimSlash(consoleHost)
  return trimSlash(site.hosts.api)
}

// current 返回本次请求要用的账号，必要时续期。
async function current(site, client, auth) {
  const a = account(auth)
  if (!expired(a)) return a
  if (!a.refresh) {
    if (a.access) return a
    throw new Error(`${site.name} 的登录已失效，请重新登录`)
  }
  return renew(site, client, a)
}

// renew 花掉一次 refresh token，同一个 refresh 只花一次。
function renew(site, client, a) {
  const key = `${site.id}\n${a.refresh}`
  let step = renewing.get(key)
  if (!step) {
    step = (async () => {
      // 先试设备绑定那条路：换出来的 JWT 绑在设备上，签到才被接受；不行再回落
      const got = await renewToken(site, a)
      const next = {
        ...a,
        access: got.access || a.access,
        refresh: got.refresh || a.refresh,
        // 上游可能不回传到期时间：0 不能覆盖已有的有效值，否则每个请求都会刷新
        expires: got.expires > 0 ? got.expires : a.expires,
        // 设备密钥（第一次续期时生成）随账号保存，下次续期还用同一把
        devicePublicKey: got.devicePublicKey || a.devicePublicKey,
        devicePrivateKey: got.devicePrivateKey || a.devicePrivateKey,
      }
      try {
        // 只把变化过的字段写回：magpie 的 auth.set 是合并语义
        await client?.auth?.set?.({
          path: { id: site.id },
          body: {
            type: "oauth",
            access: next.access,
            refresh: next.refresh,
            expires: next.expires,
            uid: next.uid,
            machineId: next.machineId,
            deviceId: next.deviceId,
            domain: next.domain || site.webHost,
            ...(next.devicePublicKey && next.devicePrivateKey ? { devicePublicKey: next.devicePublicKey, devicePrivateKey: next.devicePrivateKey } : {}),
          },
        })
      } catch {
        // 保存失败不影响本次请求；下一次请求会再刷
      }
      return next
    })().finally(() => renewing.delete(key))
    renewing.set(key, step)
  }
  return step
}

// lapsedError 判断账号域的错误是不是「令牌不被认了」（与余额 / 签到接口的普通
// 故障区分开：只有前者值得先换一次令牌再重试）。
function lapsedError(e) {
  return /HTTP\s*(401|403)/.test(String(e?.message ?? e))
}

// withAuth 拿可用账号跑一次账号域调用；令牌失效时强制换一次再重试。
//
// 对 llm-api 的 RefreshKey（签到 401 重试）：续期与访问令牌的到期时间无关，
// 所以这里不看 expires，直接花一次 refresh token。
async function withAuth(site, client, auth, run) {
  const a = await current(site, client, auth)
  try {
    return { a, value: await run(a) }
  } catch (e) {
    if (!lapsedError(e)) throw e
    if (!a.refresh) {
      e.status = 401
      throw e
    }
    const next = await renew(site, client, a)
    try {
      return { a: next, value: await run(next) }
    } catch (e2) {
      if (lapsedError(e2)) e2.status = 401
      throw e2
    }
  }
}

// errorResponse 是给客户端 / magpie 看的错误响应。
//
// type 按状态码给：401 是登录问题、429 是额度/限频（客户端会据此退避重试）、
// 其余当上游错误。
function errorResponse(message, status, signIn) {
  const type = status === 401 ? "authentication_error" : status === 429 ? "rate_limit_error" : "api_error"
  return new Response(JSON.stringify({ error: { message, type } }), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...(signIn ? { "X-Magpie-Sign-In": signIn } : {}),
    },
  })
}

// bodyText 把 fetch 的各种 body 形态读成字符串。
async function bodyText(init, req) {
  const body = init?.body ?? (req ? await req.clone().text() : undefined)
  if (body === undefined || body === null) return ""
  if (typeof body === "string") return body
  if (body instanceof ArrayBuffer) return new TextDecoder().decode(body)
  if (ArrayBuffer.isView(body)) return new TextDecoder().decode(body)
  if (typeof body.getReader === "function") return new Response(body).text()
  return String(body)
}

// wrongFunction 判断「这个模型这条通道不认」：换一个 function 重试可能就通。
// 码表在 sites.mjs 的 WRONG_FUNCTION（4001 / 4023 / 1005）。
function wrongFunction(code) {
  return WRONG_FUNCTION.includes(String(code ?? ""))
}

// functionOrder 是本次请求要试的 function 顺序：
//
//	① 模型表说这个模型走的那张（aggregateModels 挑出来的 fn）
//	② 上次真的服务过它的那张（同进程里换过一次之后直接用对的）
//	③ 站点自己的顺序（chat_v3 先，其余 SOLO 各模式）
//
// 只试这几张，不试全网：多一张表就是多一次会花钱的请求。
function functionOrder(model, entry, served, site) {
  const list = [entry?.fn, served, ...(Array.isArray(site.functions) ? site.functions : FUNCTIONS)]
  return [...new Set(list.filter(Boolean))]
}

// attemptChat 发一次对话请求，返回 { res, answer } 或 { fail, code }。
//
// 返回 answer 而不是直接把响应建出来，是因为要在「已经读到流里第一个正事事件」之后
// 才能判断这张 function 是不是真接了这个模型：上游的业务错误（4001 / 4023）不走
// HTTP 状态码，而是流里第一个 event:error。读到它之前不能把响应交给客户端，否则
// 换 function 重试就没机会了。
//
// 读过的字节全部留着：换下一张表时丢掉，决定要用时由 replayStream 原样吐回去。
//
// host 是这次要打的网关：企业账号走它租户的 console，其余走站点网关。console 回
// 4245 是「这个席位不在 console 上对话」（不是这个模型 / 这张表的问题），交给调用方
// 换网关重试。
async function attemptChat({ site, a, prepared, init, host = trimSlash(site.hosts.api) }) {
  let enc
  try {
    enc = encryptBody(JSON.stringify(prepared))
  } catch (e) {
    return { fail: errorResponse(`请求体加密失败：${e?.message ?? String(e)}`, 500) }
  }

  const headers = soloHeaders(a, { stream: true, site })
  headers["X-Request-Pin"] = enc.requestPin
  headers["X-Requested-At"] = enc.requestedAt

  let res
  try {
    res = await fetch(`${trimSlash(host)}${EP.chat}`, {
      method: "POST",
      headers,
      body: enc.bodyBase64,
      ...(init?.signal ? { signal: init.signal } : {}),
    })
  } catch (e) {
    return { fail: errorResponse(`${site.name} 连不上：${e?.message ?? String(e)}`, 502) }
  }
  if (!res.ok) {
    const body = await res.text()
    const parsed = errorOf(body)
    const fail = classify(site, { status: res.status, ...parsed })
    return { fail: errorResponse(fail.message, fail.status, fail.signIn), code: parsed.code }
  }
  // 实测形态：HTTP 200 但回的是一段 JSON（错误写在里面）。不拦就会当成空流，
  // 客户端什么都收不到还以为是模型没说话。
  const contentType = res.headers.get("content-type") ?? ""
  if (contentType.includes("json") && !contentType.includes("event-stream")) {
    const body = await res.text()
    const parsed = errorOf(body)
    const fail = classify(site, { status: 200, ...parsed })
    return { fail: errorResponse(fail.message, fail.status, fail.signIn), code: parsed.code }
  }

  // 读到流里第一个「正事」事件为止（用量 / 排队 / 心跳不算）
  const head = await peekAnswer(res.body)
  const first = head.events.find(isAnswerEvent)
  if (first && isErrorEvent(first)) {
    // 上游的业务错误：先按同一口径分类（额度类给 429、令牌失效给 401），
    // 再把码交给调用方决定要不要换下一张表重试。不分类就直接 502 的话，
    // 额度不足会被当成上游挂了。
    const fail = classifyStreamError(site, first)
    const failure = errorResponse(fail.message, fail.status, fail.signIn)
    if (wrongFunction(first.errorCode)) {
      // 这张表不认这个模型：把它读过的流放掉，让调用方换下一张
      await head.reader?.cancel?.().catch?.(() => {})
    } else {
      // 不是通道问题（额度 / 令牌 / 参数）：不再换表，错误直接给它
      await head.reader?.cancel?.().catch?.(() => {})
    }
    return { fail: failure, code: first.errorCode }
  }
  const body = replayStream(head)
  // 模型声明了的工具：文本形态的调用只在声明了工具时才解析（没声明就一定是散文）
  const tools = Array.isArray(prepared.tools) ? prepared.tools : []
  return {
    res: true,
    answer: ({ id, model, created, includeUsage, wantsStream, site: s }) => {
      if (!wantsStream) {
        // 上游只会给 SSE，客户端要一次性结果就由这里聚合
        return (async () => {
          const events = await readAll(body)
          let result
          try {
            result = aggregate(events, { tools })
          } catch (e) {
            const fail = classifyStreamError(s, e)
            return errorResponse(fail.message, fail.status, fail.signIn)
          }
          return new Response(JSON.stringify(completionOf({ id, model, created, result, usage: result.usage })), {
            status: 200,
            headers: { "Content-Type": "application/json", "X-Magpie-Sign-In": "kept" },
          })
        })()
      }
      return new Response(sseStream(body, { id, model, created, includeUsage, site: s, tools }), {
        status: 200,
        headers: { "Content-Type": "text/event-stream; charset=utf-8", "Cache-Control": "no-store", "X-Magpie-Sign-In": "kept" },
      })
    },
  }
}

// isAnswerEvent 判断一个事件是不是「正事」：正文 / 思维链 / 工具调用 / 结束 / 错误。
// 用量、排队、metadata 这些都不算——读到它们不能说明这张 function 接了。
function isAnswerEvent(ev) {
  return ev?.event === "error" || ev?.event === "thought" || !!ev?.response || !!ev?.reasoning || !!ev?.toolCalls || !!ev?.finishReason || ev?.errorCode !== undefined
}

// isErrorEvent 判断一个事件是不是上游的业务错误。
function isErrorEvent(ev) {
  return ev?.event === "error" || (ev?.errorCode !== undefined && ev?.errorCode !== 0)
}

// peekAnswer 从流里读到第一个正事事件为止，把读过的字节留着。
//
// 返回 { events, chunks, reader }：reader 为 null 说明流已经读完了（很短的回答）。
// 读过的 chunks 交给 replayStream 原样吐回，所以调用方不需要自己处理「已经读掉的
// 那一段」。
async function peekAnswer(upstream) {
  const reader = upstream.getReader()
  const td = new TextDecoder()
  const dec = new SoloDecoder()
  const chunks = []
  const events = []
  for (;;) {
    const { done, value } = await reader.read()
    if (done) return { events, chunks, reader: null }
    chunks.push(value)
    events.push(...dec.push(td.decode(value, { stream: true })))
    if (events.some(isAnswerEvent)) return { events, chunks, reader }
  }
}

// replayStream 把 peekAnswer 读过的字节重放一遍，再接上剩下的流。
//
// 重放走的是新的解码器，所以 peek 时那个解码器的半行状态不会被带过来。
function replayStream({ chunks, reader }) {
  let i = 0
  return new ReadableStream({
    async pull(controller) {
      if (i < chunks.length) {
        controller.enqueue(chunks[i++])
        return
      }
      if (!reader) {
        controller.close()
        return
      }
      const { done, value } = await reader.read()
      if (done) {
        controller.close()
        return
      }
      controller.enqueue(value)
    },
    cancel(reason) {
      return reader?.cancel?.(reason)?.catch?.(() => {})
    },
  })
}

// makePlugin 为站点造一个插件函数。
export function makePlugin(site) {
  return async ({ client }) => {
    // 版本探测：本机装了 Trae IDE 就直接读它的版本，没装才去问上游的最新版本。
    // 放在插件装配时（不是请求路径上），失败就继续用内置常量。
    startIdeVersionRefresh(site, { mid: PROFILE.machineID })
    // 每个账号的模型清单缓存：uid → { at, list }
    const lists = new Map()
    // 每个账号里「哪个模型最后是被哪张 function 服务成功的�
…[文件过长——中段 8KB 抽样]…
rovider, m)]))
          }
          try {
            const list = await fetchModels(site, a)
            if (!list.length) return provider.models
            lists.set(cacheKey, { at: Date.now(), list })
            if (lists.size > 32) lists.delete(lists.keys().next().value)
            return Object.fromEntries(list.map((m) => [m.id, modelOf(provider, m)]))
          } catch {
            return provider.models
          }
        },
      },
      auth: {
        provider: site.id,
        refreshLead: LEAD_MS,
        // magpie 到期前 LEAD_MS 主动续期
        refresh: async (auth) => {
          if (!usable(auth) || !auth.refresh) return undefined
          const got = await renewToken(site, account(auth))
          const out = {}
          if (got.access && got.access !== auth.access) out.access = got.access
          if (got.refresh && got.refresh !== auth.refresh) out.refresh = got.refresh
          if (got.expires > 0 && got.expires !== auth.expires) out.expires = got.expires
          if (got.devicePrivateKey && got.devicePrivateKey !== auth.devicePrivateKey) {
            out.devicePublicKey = got.devicePublicKey
            out.devicePrivateKey = got.devicePrivateKey
          }
          return Object.keys(out).length ? out : undefined
        },
        async loader(getAuth) {
          const placeholder = site.id
          return {
            apiKey: placeholder,
            async fetch(input, init = {}) {
              const auth = await getAuth()
              if (!usable(auth)) {
                return errorResponse(`${site.name} 未登录，请先在 magpie 登录`, 401, "expired")
              }
              let a
              try {
                a = await current(site, client, auth)
              } catch (e) {
                return errorResponse(e?.message ?? String(e), 401, "expired")
              }
              const req = input instanceof Request ? input : null
              const text = await bodyText(init, req)
              let chat
              try {
                chat = JSON.parse(text)
              } catch {
                return errorResponse("只接受 chat/completions 的 JSON 请求体", 400)
              }
              if (!chat || typeof chat !== "object") {
                return errorResponse("只接受 chat/completions 的 JSON 请求体", 400)
