// readAll 把整条 SSE 读完并解析成事件列表。
async function readAll(upstream) {
  const decoder = new SoloDecoder()
  const events = []
  const reader = upstream.getReader()
  const td = new TextDecoder()
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    events.push(...decoder.push(td.decode(value, { stream: true })))
  }
  events.push(...decoder.end())
  return events
}

// sseStream 把 SOLO 事件流翻译成 OpenAI 的 SSE。
//
// finish_reason 有工具调用时必须是 tool_calls，否则客户端不会去执行工具；上游没
// 发 done 就断流时也要收尾，否则客户端永远等在最后一片上。
function sseStream(upstream, { id, model, created, includeUsage, site, tools = [] }) {
  const decoder = new SoloDecoder()
  const td = new TextDecoder()
  // 正文里写成文本的调用：模型（GLM / DeepSeek / Kimi）常常把调用写进正文而不走
  // 结构化 tool_calls。这里逐片喂给 TextTools，它把标签与 JSON 留在自己的 buf 里，
  // 整了才吐出来——不会把半个调用当正文发给客户端。
  const tt = tools.length ? new TextTools(tools) : null
  // 客户端中途关掉时（用户按 Esc、客户端超时）要主动把上游流也取消：不取消就会
  // 接着把整个回答读完，白烧积分，也只会在下一个 enqueue 上才报错。
  let reader
  let closed = false
  return new ReadableStream({
    async start(controller) {
      const enc = new TextEncoder()
      const send = (obj) => {
        if (closed) return
        try {
          controller.enqueue(enc.encode(`data: ${JSON.stringify(obj)}\n\n`))
        } catch {
          closed = true
        }
      }
      const sendDone = () => {
        if (closed) return
        try {
          controller.enqueue(enc.encode("data: [DONE]\n\n"))
        } catch {
          closed = true
        }
      }
      let sawToolCall = false
      let lastFinish = ""
      let usage
      let failed = false
      const thoughts = new Thoughts()

      const emit = (events) => {
        for (const ev of events) {
          if (ev.event === "thought" || ev.response || ev.reasoning || ev.toolCalls) {
            const calls = toolCallsOf(ev)
            if (calls.length) sawToolCall = true
            // 思维链会重复发（同一段连发两次 / 把「目前为止的全部」再发一遍）
            const reasoning = ev.reasoning ? thoughts.add(ev.reasoning) : ""
            const content = ev.response ?? ""
            if (!content && !reasoning && !calls.length) continue
            const delta = {}
            if (content) delta.content = content
            if (reasoning) delta.reasoning_content = reasoning
            if (calls.length) delta.tool_calls = calls
            send(chunkOf({ id, model, created, delta }))
            // 正文里的文本调用：与原生调用同时存在也照读（模型通常只写一种）
            if (tt && content) {
              const r = tt.push(content)
              flushText(r)
            }
          }
          if (ev.usage) usage = ev.usage
          if (ev.finishReason) lastFinish = ev.finishReason
          if (ev.event === "error") {
            // 上游业务错误（额度 / token 失效 / 参数无效）不能静默吞掉：
            // 否则客户端只收到一个空流。分类与 HTTP 层同一口径。
            failed = true
            const fail = classifyStreamError(site, ev)
            send({ error: { message: fail.message, type: fail.type, code: ev.errorCode || null } })
          }
        }
      }

      // flushText 把 TextTools 吐出来的东西发出去：正文、思维链、文本形态的调用，
      // 以及「读不出来」的错误。一个读不出来的块不当正文发——半个调用发给客户端
      // 比报错更糟。
      const flushText = (r) => {
        if (r.reasoning) {
          const t = thoughts.add(r.reasoning)
          if (t) send(chunkOf({ id, model, created, delta: { reasoning_content: t } }))
        }
        if (r.text) send(chunkOf({ id, model, created, delta: { content: r.text } }))
        if (r.calls?.length) {
          sawToolCall = true
          send(chunkOf({ id, model, created, delta: { tool_calls: r.calls.map(textCall) } }))
        }
        if (r.error) {
          failed = true
          send({ error: { message: r.error, type: "api_error", code: null } })
        }
      }

      try {
        reader = upstream.getReader()
        for (;;) {
          const { done, value } = await reader.read()
          if (done) break
          if (closed) break
          emit(decoder.push(td.decode(value, { stream: true })))
          if (failed) break
        }
        if (!failed && !closed) emit(decoder.end())
      } catch (e) {
        if (!closed) {
          failed = true
          send({ error: { message: e?.message ?? String(e), type: "api_error" } })
        }
      }

      if (!failed) {
        // 流结束时把 TextTools 里还压着的尾巴冲出来（一个写完了的块、
        // 或一个截断了的块——后者是错误）
        if (tt && !closed) flushText(tt.push("", true))
      }
      if (!failed) {
        const finish = sawToolCall ? "tool_calls" : lastFinish || "stop"
        send(chunkOf({ id, model, created, delta: {}, finishReason: finish }))
        if (includeUsage && usage) {
          send({ id, object: "chat.completion.chunk", created, model, choices: [], usage })
        }
      }
      sendDone()
      if (!closed) {
        try {
          controller.close()
        } catch {
          closed = true
        }
      }
    },
    async cancel(reason) {
      closed = true
      try {
        await reader?.cancel(reason)
      } catch {
        // 上游已经结束了：取消失败没什么可做的
      }
    },
  })
}

// creditsWindow 把消费页的 usage 卡（entUsage 的返回值）读成 { limit, used, unlimited, until, lapsing }。
//
// 企业账号的额度在 console 上，消费页只当旁列；这里只取它已经算好的窗口，
// 不重新解释一遍积分包（那套口径在 account.mjs 里）。
function creditsWindow(usage) {
  const w = Array.isArray(usage?.windows) ? usage.windows[0] : null
  if (usage?.balance === "unlimited") return { unlimited: true, limit: 0, used: 0, until: 0, lapsing: 0 }
  if (!w) return null
  const limit = Number(w.limit) || 0
  if (limit <= 0) return null
  return {
    limit,
    used: Number(w.amount) || 0,
    unlimited: false,
    until: w.resetsAt ? Date.parse(w.resetsAt) : 0,
    lapsing: Number(w.runsOut) || 0,
  }
}

// modelOf 把一条模型清单项转成 models 钩子的条目。
function modelOf(provider, m) {
  const images = m.images === true
  return {
    id: m.id,
    providerID: provider.id,
    name: m.name || m.id,
    api: { id: m.id, url: m.enterprise && provider.console ? provider.console : provider.api ?? "" },
    status: "active",
    headers: {},
    options: {},
    cost: { input: 0, output: 0, cache: { read: 0, write: 0 } },
    limit: { context: m.context ?? 0, output: m.output ?? 0 },
    capabilities: {
      temperature: true,
      reasoning: m.reasoning === true,
      attachment: images,
      toolcall: m.toolcall !== false,
      input: { text: true, image: images, audio: false, video: false, pdf: false },
      output: { text: true, image: false, audio: false, video: false, pdf: false },
      interleaved: false,
    },
    release_date: "",
    // 档位：上游声明了才有，名字用客户端认的那套（发请求时再翻回 Trae 的名字）
    variants: Object.fromEntries((Array.isArray(m.efforts) ? m.efforts : []).map((e) => [e, {}])),
    // magpie 自己的：credits 倍数（0 = 免费，路由会优先用）
    ...(m.rate === 0 ? { free: true } : {}),
    ...(typeof m.rate === "number" ? { rate: m.rate } : {}),
  }
}
